def load_data():
    summary = json.loads((AUDIT / 'summary.json').read_text(encoding='utf-8'))
    ledger = json.loads((AUDIT / 'reviewed_evidence.json').read_text(encoding='utf-8'))
    plan = json.loads((ROOT / 'data/weekly_smoke_20261119/plan.json').read_text(encoding='utf-8'))
    validation = json.loads((AUDIT / 'validation.json').read_text(encoding='utf-8'))
    with (AUDIT / 'funding_outcomes_candidate.csv').open(encoding='utf-8', newline='') as stream:
        rows = list(csv.DictReader(stream))
    counts = Counter(row['funding_evidence_status'] for row in rows)
    assert len(rows) == 240 and summary['candidate_disclosure_companies'] == 103
    assert len(ledger['reviews']) == 13 and validation['offline_tests']['passed'] == 142
    assert summary['original_13_round_dates_undetermined'] == 13
    return summary, ledger['reviews'], plan, counts


def company_table_html(reviews):
    records = []
    for r in reviews:
        precision = '日（僅供應商顯示）' if r['provider_precision'] == 'DAY' else '未報精度'
        source = escape(r['provider_round_url'], quote=True)
        records.append(f'<tr><td><a href="{source}">{escape(r["name_at_decision"])}</a></td>'
                       f'<td>{r["provider_reported_date"]}</td><td>{precision}</td>'
                       f'<td>{COMPANY_NOTES[r["company_id"]]}</td><td>未定</td></tr>')
    return '<div class="table-wrap"><table><thead><tr><th>決策時公司名稱</th><th>供應商日期</th><th>日期精度</th><th>本週查核結果</th><th>原輪次</th></tr></thead><tbody>' + ''.join(records) + '</tbody></table></div>'


def figure_html(index):
    name, title, caption = CHARTS[index - 1]
    return f'<figure><a href="figures/{name}"><img src="figures/{name}" alt="{escape(title)}" loading="lazy"></a><figcaption><span>FIG {index:02d}</span> {caption}</figcaption></figure>'


