def build_pdf(reviews, output=PDF):
    from PIL import Image as PILImage
    from reportlab.lib import colors
    from reportlab.lib.enums import TA_LEFT
    from reportlab.lib.pagesizes import A4
    from reportlab.lib.styles import ParagraphStyle
    from reportlab.pdfbase import pdfmetrics
    from reportlab.pdfbase.ttfonts import TTFont
    from reportlab.pdfgen.canvas import Canvas
    from reportlab.platypus import Paragraph, Table, TableStyle

    if not FONT.exists():
        raise FileNotFoundError(f'Chinese font missing: {FONT}')
    pdfmetrics.registerFont(TTFont('ReportCJK', str(FONT)))
    for name, _, _ in CHARTS:
        if not (REPORT / 'figures' / name).exists():
            raise FileNotFoundError(f'Generate the seven chart PNGs first: {name}')
    output.parent.mkdir(parents=True, exist_ok=True)
    c = Canvas(str(output), pagesize=A4, pageCompression=1)
    c.setTitle('W24 Historical Research - Weekly Data Report - 2026-11-19')
    c.setAuthor('Yi-Nung, with AI assistance; existing team provenance retained')
    W, H = A4
    M, CW = 43, W - 86
    INK, MUTED, TEAL = colors.HexColor('#142c3c'), colors.HexColor('#5d6b76'), colors.HexColor('#087e86')
    LIGHT, LINE = colors.HexColor('#edf5f4'), colors.HexColor('#dbe4e8')
    overflow = []

    def p(text, y, width=CW, x=M, size=9.7, leading=15, color=INK):
        style = ParagraphStyle('body', fontName='ReportCJK', fontSize=size, leading=leading,
                               textColor=color, wordWrap='CJK', alignment=TA_LEFT,
                               spaceAfter=0, allowWidows=0, allowOrphans=0)
        paragraph = Paragraph(text, style)
        _, height = paragraph.wrap(width, H)
        paragraph.drawOn(c, x, y - height)
        if y - height < 43:
            overflow.append((c.getPageNumber(), text[:70], y - height))
        return y - height

    def begin(number, title, subtitle):
        c.setFillColor(TEAL); c.setFont('ReportCJK', 8)
        c.drawString(M, H - 32, 'COLUMBIA IEOR 4511  |  W24 HISTORICAL RESEARCH')
        c.drawRightString(W - M, H - 32, '2026-11-19')
        c.setStrokeColor(LINE); c.setLineWidth(.6); c.line(M, H - 42, W - M, H - 42)
        c.setFillColor(TEAL); c.setFont('ReportCJK', 9)
        c.drawString(M, H - 65, f'{number:02d} / WEEKLY DATA REPORT')
        y = p(title, H - 78, size=22, leading=30)
        return p(subtitle, y - 9, size=9.4, leading=14.2, color=MUTED) - 14

    def footer():
        c.setStrokeColor(LINE); c.line(M, 35, W - M, 35)
        c.setFillColor(MUTED); c.setFont('ReportCJK', 7)
        c.drawString(M, 23, 'Evidence coverage, not investment success. UNKNOWN is not zero.')
        c.drawRightString(W - M, 23, f'{c.getPageNumber()} / 6')
        c.showPage()

    def image(index, top, width=CW, x=M, maxheight=None, caption=True):
        name, _, text = CHARTS[index - 1]
        path = REPORT / 'figures' / name
        iw, ih = PILImage.open(path).size
        height = width * ih / iw
        if maxheight and height > maxheight:
            width *= maxheight / height; height = maxheight
        c.drawImage(str(path), x, top - height, width=width, height=height, mask='auto')
        bottom = top - height
        if caption:
            bottom = p(f'FIG {index:02d}  {text}', bottom - 5, width=width, x=x,
                       size=8.1, leading=12, color=MUTED)
        return bottom - 12

    def table(headers, rows, y, widths, size=8.3, leading=12, pad=6):
        style = ParagraphStyle('cell', fontName='ReportCJK', fontSize=size, leading=leading,
                               textColor=INK, wordWrap='CJK')
        values = [[Paragraph(escape(str(v)), style) for v in row] for row in [headers, *rows]]
        t = Table(values, colWidths=widths, hAlign='LEFT')
        t.setStyle(TableStyle([
            ('BACKGROUND', (0, 0), (-1, 0), LIGHT),
            ('LINEBELOW', (0, 0), (-1, -1), .5, LINE),
            ('VALIGN', (0, 0), (-1, -1), 'TOP'),
            ('LEFTPADDING', (0, 0), (-1, -1), pad),
            ('RIGHTPADDING', (0, 0), (-1, -1), pad),
            ('TOPPADDING', (0, 0), (-1, -1), pad),
            ('BOTTOMPADDING', (0, 0), (-1, -1), pad)]))
        _, h = t.wrap(CW, H)
        t.drawOn(c, M, y - h)
        if y - h < 43:
            overflow.append((c.getPageNumber(), 'table', y - h))
        return y - h - 12

    y = begin(1, '本週資料進度：新增 1 家披露候選',
              '鎖定 240 家公司｜決策資訊截止 2024-04-04｜嚴格結果窗口 2024-04-05 至 2026-04-04')
    y = p('本週完成日期逐筆審核、受限研究後端與獨立 smoke test 計畫。可核對的資料增量很小：TrueClaim 另有一筆第一方投資人披露；原 13 筆供應商輪次仍未補出原公告精度。', y) - 16
    stat_w = CW / 4
    metrics = [('103 / 240', '嚴格披露候選', '42.92% · 上週 102 家'),
               ('137 家', '披露尚未建立', '未知，不是未融資'),
               ('13 / 13', '原輪次仍未定', '原公告精度未補出'),
               ('142 項', '離線測試通過', '不代表模型準確率')]
    c.setStrokeColor(LINE); c.line(M, y, M + CW, y)
    for i, (value, label, detail) in enumerate(metrics):
        x = M + i * stat_w
        p(label, y - 10, x=x, width=stat_w - 8, size=8.3, leading=12, color=MUTED)
        p(value, y - 28, x=x, width=stat_w - 8, size=21, leading=28)
        p(detail, y - 61, x=x, width=stat_w - 8, size=7.3, leading=11, color=MUTED)
    y -= 91
    y = image(1, y)
    y = p('102 → 103 家：增加 1 家、0.42 個百分點。90% 至少需 216 家，尚差 113 家。融資負例仍為 0，尚無雙類別評估集。', y, size=10.4, leading=16) - 12
    p('PR #3 的 164/240 為不同定義的綜合觀測：153 筆融資觀測＋11 家額外狀態觀測，非 SEC 報道窗口延至 2026-07-04；不能接成同一口徑的覆蓋成長。', y, size=9.2, leading=14)
    footer()

    y = begin(2, '資料缺口：137 家尚未建立披露',
              '候選表只改 TrueClaim 的披露欄位；交易與負例欄位均未改動。')
    y = image(2, y, maxheight=290)
    y = image(3, y - 5, width=300, maxheight=205, caption=False)
    p('披露與 SEC 證據分開', y + 205, x=M + 316, width=CW - 316, size=12, leading=17)
    p('92 家僅披露、11 家兩者都有、1 家僅 SEC、136 家兩者均未建立。<br/><br/>交叉表只描述證據維度，不能加成「104 家嚴格融資正例」。', y + 174, x=M + 316, width=CW - 316, size=9.4, leading=15)
    y = p('FIG 03  103 家公開披露與 12 家 SEC 首售有 11 家重疊。此交叉表不改變嚴格披露候選數，也不驗證「未融資」。', y - 2, size=8.2, leading=12, color=MUTED) - 12
    p('上週文字的「117 家未回傳事件」無法由共享 CSV 精確重現；共享表該類別為 108 家，其餘未知類型分開保留。缺少原始回應，不能由差額判斷原因。', y, size=9.4, leading=15)
    footer()

    y = begin(3, '13 家日期查核：檢查完成，精度仍未解',
              '多數儲存連結是供應商頁，而非原公司／投資人公告。11 筆 2026-01-01 不能自動解讀為精確的日。')
    y = image(4, y, maxheight=255, caption=False)
    data_rows = [[r['name_at_decision'], r['provider_reported_date'],
                  '僅顯示日' if r['provider_precision'] == 'DAY' else '未報精度',
                  COMPANY_NOTES[r['company_id']]] for r in reviews]
    y = table(['公司', '供應商日期', '精度', '本週查核結果；原輪次均維持未定'], data_rows,
              y, [92, 79, 59, CW - 230], size=7.9, leading=11.3, pad=4.5)
    p('TrueClaim 的 2024-06-12 投資人披露另列，未與原 2026 輪次配對。Haplotype 首售 2024-03-29 在窗前，未以較晚申報日改寫，也未推論公司後續無融資。', y, size=8.6, leading=13)
    footer()

    y = begin(4, '來源時間：先分語義，再查邊界',
              '「約三個月」只用作人工複核帶。未測得來源別延遲分布，不自動平移日期或採納寬限窗。')
    y = table(['來源／欄位', '日期語義', '採用規則'], SOURCE_RULES, y,
              [153, 151, CW - 304], size=8.3, leading=12.5, pad=5.5)
    y = image(5, y - 4, width=440, maxheight=260)
    p('起點複核帶：2024-01-05 至 2024-07-05；終點複核帶：2026-01-04 至 2026-07-04。55 家是顯示日期接近邊界；額外 29 家來自未報精度的保守擴展。84 家不是新增正例。', y, size=9.2, leading=14)
    footer()

    y = begin(5, '工程證據：後端有迴圈，品質待實跑',
              '限定已觀測的歷史公司網站路徑；資料先驗證才供模型選路。一般新聞與同業探索尚未完成。')
    y = image(6, y, maxheight=232)
    y = image(7, y - 2, maxheight=242)
    p('新增 38 項：研究後端 15、smoke runner 14、日期稽核 8、prompt cache 1。缺 usage、API／會計錯誤及錯誤 citation 會阻止後續呼叫；被拒重跑保留舊結果。', y, size=9.2, leading=14) - 10
    p('142 項都是離線流程、合成回應與防護測試；它們不量測研究正確率、投資報酬、模型準確率，也未建立模型預訓練完全無未來資訊的保證。', y - 43, size=9.2, leading=14)
    footer()

    y = begin(6, '下一步：把未定資料變成可審核證據',
              '本週依使用者選擇僅交付程式與計畫：新模型執行 0 次、US$0；不重用已封存 Abel pilot。')
    y = table(['Adagy Robotics 獨立 smoke plan', '固定上限／停止條件'], [
        ['公司／資訊截止', '1 家；2024-04-04 23:59:59 UTC；不依 Y 選樣'],
        ['模型／成本', '最多 24 次 API；US$0.20 保守成本預留上限（未執行）'],
        ['網頁／執行', '最多 6 次 Archive HTTP；8 分鐘 deadline；2 次研究 pass'],
        ['錯誤停止', '缺 usage、provider／schema／citation 錯誤、無新證據即停'],
        ['輸出與隔離', '保存 result、stop reason、receipt、成本預留；不讀 Y 或現代公司檔案'],
    ], y, [174, CW - 174], size=9, leading=14, pad=7)
    y = p('後續工作與交付標準', y - 1, size=13, leading=20) - 10
    actions = [
        '1. 找回 13 筆原公告與日期精度；找不到就維持未定，不以目前支持標記補成確定日期。',
        '2. 從邊界清單配對同一輪次交易日／公告日，再討論來源別延遲或窗口規則。',
        '3. 人工複核 TrueClaim 候選；PR #3 修正 LF／CRLF 雜湊與中文舊數字，但不因此改標籤。',
        '4. 修復 Crunchbase 存取狀態後再取欄位。現有檢查為 current 401、legacy 404，未取得商業資料。',
        '5. 若未來另獲授權，先核對模型費率及既有設定，再只跑保存的 Adagy 計畫。',
    ]
    for text in actions:
        y = p(text, y, size=9.6, leading=15) - 9
    y = p('給 Jeff：三個月延遲來自哪些來源與樣本？用途是人工複核帶，還是另行核准的報道窗口規則？本週沒有足夠配對樣本可估計該延遲。', y - 3, size=10, leading=15.5) - 16
    y = p('資料與重建', y, size=12, leading=18) - 6
    y = p('圖文報告與圖表資料：docs/updates/2026-11-19-visual-report/；候選／日期／邊界 CSV 與 manifest：data/weekly_audit_20261119/。<br/>圖表計算：scripts/analyze_weekly_report.py；視覺報告：scripts/build_weekly_visual_report.py。', y, size=8.5, leading=13) - 10
    y = p(f'<link href="{REPO}/pull/4" color="#087e86">GitHub PR #4（本週交付）</link> · '
          f'<link href="{REPO}/pull/2" color="#087e86">PR #2（上週）</link> · '
          f'<link href="{REPO}/pull/3" color="#087e86">PR #3（不同口徑）</link>', y, size=8.5, leading=13) - 8
    p('Prepared for Yi-Nung with AI assistance. Rose Yu 與既有團隊研究／程式來源保留。本報告未包含金鑰或 raw provider payload。', y, size=8.2, leading=12, color=MUTED)
    footer()
    if overflow:
        raise RuntimeError(f'PDF content overflow: {overflow}')
    c.save()
    from pypdf import PdfReader
    reader = PdfReader(str(output))
    assert len(reader.pages) == 6
    print(json.dumps({'pdf': str(output), 'pages': len(reader.pages), 'layout_overflow': False,
                      'bytes': output.stat().st_size, 'sha256': hashlib.sha256(output.read_bytes()).hexdigest()}))


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--html-only', action='store_true')
    parser.add_argument('--pdf-output', type=Path, default=PDF)
    args = parser.parse_args()
    _, reviews, _, _ = load_data()
    REPORT.mkdir(parents=True, exist_ok=True)
    build_html(reviews)
    build_readme()
    print(json.dumps({'html': str(REPORT / 'index.html'), 'readme': str(REPORT / 'README.md')}))
    if not args.html_only:
        build_pdf(reviews, args.pdf_output)


if __name__ == '__main__':
    main()
